// Generated from src/webview/panel.html by scripts/lib.mjs. Edit that file, then run a build.
export const WEBVIEW_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n<title>Sprint Board</title>\n<style id=\"theme\">:root{/*__DD_THEME__*/}</style>\n<style>\n/* Panel UI for the Sprint Board extension. Colors, type and radii come from\n   Drawdy's --dd-* tokens (injected above); the fallbacks keep it usable without them.\n   Layout: a fixed header (sprint, progress, actions), tabs, filters, then a scrolling list. */\n:root {\n    --bg: var(--dd-surface-panel, #ffffff);\n    --well: var(--dd-surface-section, #f3f4f6);\n    --raised: var(--dd-surface-elevated, #ffffff);\n    --scrim: var(--dd-surface-overlay, rgba(15, 18, 24, 0.4));\n    --fg: var(--dd-text-primary, #1f2328);\n    --fg2: var(--dd-text-secondary, #59636e);\n    --fg3: var(--dd-text-tertiary, #8b949e);\n    --line: var(--dd-border-subtle, #e1e4e8);\n    --line2: var(--dd-border-medium, #c9ced4);\n    --divider: var(--dd-divider, #eceef1);\n    --hover: var(--dd-interaction-hover, rgba(0, 0, 0, 0.05));\n    --active: var(--dd-interaction-active, rgba(0, 0, 0, 0.08));\n    --accent: var(--dd-accent, #4263eb);\n    --accent-hover: var(--dd-accent-hover, #3b5bdb);\n    --accent-text: var(--dd-accent-text, #364fc7);\n    --accent-subtle: var(--dd-accent-subtle, rgba(66, 99, 235, 0.12));\n    --on-accent: var(--dd-on-accent, #ffffff);\n    --danger: var(--dd-status-danger, #c92a2a);\n    --danger-subtle: var(--dd-status-danger-subtle, rgba(201, 42, 42, 0.1));\n    --success: var(--dd-status-success, #2b8a3e);\n    --warning: var(--dd-status-warning, #b35c00);\n    --warning-subtle: var(--dd-status-warning-subtle, rgba(240, 140, 0, 0.12));\n    --focus: var(--dd-focus-ring, #868e96);\n    --sans: var(--dd-font-sans, ui-sans-serif, system-ui, -apple-system, \"Segoe UI\", sans-serif);\n    --mono: var(--dd-font-mono, ui-monospace, \"SFMono-Regular\", Menlo, Consolas, monospace);\n    --r-sm: var(--dd-radius-sm, 4px);\n    --r-md: var(--dd-radius-md, 6px);\n    --r-lg: var(--dd-radius-lg, 8px);\n    --control: var(--dd-control-sm, 30px);\n}\n* { box-sizing: border-box; }\nhtml, body { margin: 0; height: 100%; }\nbody {\n    font: 400 12px/18px var(--sans);\n    background: var(--bg);\n    color: var(--fg);\n    display: flex;\n    flex-direction: column;\n    height: 100vh;\n    overflow: hidden;\n}\nbutton, input, select, textarea { font: inherit; color: inherit; }\nbutton { cursor: pointer; }\n:focus-visible { outline: 2px solid var(--focus); outline-offset: 1px; }\n[hidden] { display: none !important; }\n\n.btn {\n    height: var(--control);\n    padding: 0 12px;\n    border-radius: var(--r-md);\n    border: 1px solid var(--line2);\n    background: var(--raised);\n    font-weight: 500;\n    white-space: nowrap;\n}\n.btn:hover { background: var(--hover); }\n.btn.primary { background: var(--accent); border-color: var(--accent); color: var(--on-accent); }\n.btn.primary:hover { background: var(--accent-hover); }\n.btn.danger { color: var(--danger); border-color: var(--danger); background: transparent; }\n.btn.danger.solid { background: var(--danger); color: #fff; }\n.btn.ghost { border-color: transparent; background: transparent; color: var(--fg2); }\n.btn.ghost:hover { background: var(--hover); color: var(--fg); }\n.btn:disabled { opacity: 0.45; cursor: not-allowed; }\n.icon-btn {\n    width: 28px; height: 28px; padding: 0;\n    display: inline-flex; align-items: center; justify-content: center;\n    border: 0; border-radius: var(--r-md); background: transparent; color: var(--fg2);\n}\n.icon-btn:hover { background: var(--hover); color: var(--fg); }\n.link { border: 0; background: none; padding: 0; color: var(--accent-text); font-weight: 500; }\n.link:hover { text-decoration: underline; }\n\n/* ---- header ---- */\n.top { padding: 12px 16px 12px; border-bottom: 1px solid var(--divider); display: grid; gap: 8px; }\n.crumb { display: flex; align-items: center; justify-content: space-between; gap: 8px; }\n.crumb-text { font-size: 11px; line-height: 16px; color: var(--fg3); letter-spacing: 0.04em; text-transform: uppercase; }\n.sprint-row { display: flex; align-items: baseline; gap: 8px; min-width: 0; }\n.sprint-name { font-size: 15px; line-height: 20px; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; text-wrap: balance; }\n.sprint-meta { color: var(--fg2); }\n.sprint-goal { color: var(--fg2); overflow-wrap: anywhere; }\n.progress { display: flex; height: 6px; border-radius: 99px; overflow: hidden; background: var(--well); }\n.progress span { display: block; height: 100%; }\n.progress-label { display: flex; justify-content: space-between; color: var(--fg3); font-size: 11px; line-height: 16px; font-variant-numeric: tabular-nums; }\n.top-actions { display: flex; gap: 8px; flex-wrap: wrap; }\n.top-actions .btn.primary { margin-left: auto; }\n\n/* ---- tabs and filters ---- */\n.tabs { display: flex; gap: 2px; padding: 0 12px; border-bottom: 1px solid var(--divider); }\n.tab {\n    border: 0; background: none; padding: 9px 8px 8px; font-weight: 500; color: var(--fg2);\n    border-bottom: 2px solid transparent; margin-bottom: -1px; display: flex; gap: 6px; align-items: center;\n}\n.tab:hover { color: var(--fg); }\n.tab[aria-selected=\"true\"] { color: var(--accent-text); border-bottom-color: var(--accent); }\n.count { font-size: 11px; line-height: 16px; padding: 0 6px; border-radius: 99px; background: var(--well); color: var(--fg2); font-variant-numeric: tabular-nums; }\n\n.filters { padding: 10px 16px; display: grid; gap: 8px; border-bottom: 1px solid var(--divider); }\n.search {\n    width: 100%; height: var(--control); padding: 0 10px; border-radius: var(--r-md);\n    border: 1px solid var(--line2); background: var(--raised);\n}\n.search::placeholder { color: var(--fg3); }\n.chips { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }\n.chip {\n    height: 26px; padding: 0 9px 0 3px; border-radius: 99px; border: 1px solid var(--line);\n    background: transparent; display: inline-flex; align-items: center; gap: 6px; font-weight: 500; color: var(--fg2);\n}\n.chip.plain { padding: 0 10px; }\n.chip:hover { background: var(--hover); }\n.chip[aria-pressed=\"true\"] { background: var(--accent-subtle); border-color: var(--accent); color: var(--accent-text); }\n.filter-row { display: flex; gap: 6px; flex-wrap: wrap; align-items: center; }\n.select {\n    height: 28px; padding: 0 8px; border-radius: var(--r-md); border: 1px solid var(--line2); background: var(--raised);\n}\n.filter-row .spacer { flex: 1; }\n\n/* ---- list ---- */\n.list { flex: 1; overflow-y: auto; padding: 4px 8px 24px; }\n.group-head {\n    display: flex; align-items: center; gap: 8px; padding: 12px 8px 4px;\n    font-size: 11px; line-height: 16px; font-weight: 600; letter-spacing: 0.04em; text-transform: uppercase; color: var(--fg3);\n}\n.group-head .dot { width: 8px; height: 8px; border-radius: 99px; }\n.row {\n    display: grid; grid-template-columns: 16px auto minmax(0, 1fr) auto auto 20px; gap: 8px; align-items: center;\n    width: 100%; padding: 6px 8px; border: 0; border-radius: var(--r-md); background: transparent; text-align: left;\n}\n.row:hover { background: var(--hover); }\n.row.highlight { background: var(--accent-subtle); }\n.row .key { font: 500 11px/16px var(--mono); color: var(--fg3); }\n.row .title { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.row .pts { font-size: 11px; line-height: 16px; padding: 0 6px; border-radius: 99px; background: var(--well); color: var(--fg2); font-variant-numeric: tabular-nums; }\n.row-wrap { display: flex; align-items: center; gap: 4px; }\n.row-wrap .row { flex: 1; min-width: 0; }\n.mini { height: 24px; padding: 0 8px; font-size: 11px; border-radius: var(--r-md); border: 1px solid var(--line); background: transparent; color: var(--fg2); white-space: nowrap; }\n.mini:hover { background: var(--hover); color: var(--fg); }\n.none { padding: 6px 8px 8px; color: var(--fg3); }\n\n.avatar {\n    width: 20px; height: 20px; border-radius: 99px; display: inline-flex; align-items: center; justify-content: center;\n    font-size: 9px; font-weight: 600; color: #fff; flex: none; letter-spacing: 0.02em;\n}\n.avatar.empty { background: transparent; border: 1px dashed var(--line2); color: var(--fg3); }\nsvg.ic { width: 16px; height: 16px; flex: none; display: block; }\n\n.release { margin: 8px 4px 12px; padding: 12px; border: 1px solid var(--line); border-radius: var(--r-lg); display: grid; gap: 6px; }\n.release-head { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }\n.release-name { font-weight: 600; font-size: 13px; }\n.release-meta { color: var(--fg3); font-size: 11px; line-height: 16px; }\n.release-notes { white-space: pre-wrap; color: var(--fg2); overflow-wrap: anywhere; }\n.release-item { display: grid; grid-template-columns: 16px auto minmax(0, 1fr) 20px; gap: 8px; align-items: center; padding: 3px 0; }\n.release-item .key { font: 500 11px/16px var(--mono); color: var(--fg3); }\n.release-item .title { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n\n.import-box { margin: 16px 4px 0; padding: 12px; border-radius: var(--r-lg); background: var(--well); color: var(--fg2); display: grid; gap: 8px; justify-items: start; }\n\n/* ---- empty and loading ---- */\n.center { flex: 1; overflow-y: auto; padding: 24px 20px; display: grid; align-content: start; gap: 14px; }\n.center h1 { margin: 0; font-size: 14px; line-height: 20px; font-weight: 600; }\n.center p { margin: 0; color: var(--fg2); max-width: 46ch; }\n\n/* ---- forms ---- */\n.field { display: grid; gap: 4px; }\n.field > span { font-size: 11px; line-height: 16px; font-weight: 500; color: var(--fg2); }\n.input, .textarea {\n    width: 100%; border-radius: var(--r-md); border: 1px solid var(--line2); background: var(--raised);\n}\n.input { height: var(--control); padding: 0 10px; }\n.textarea { padding: 8px 10px; min-height: 88px; resize: vertical; line-height: 18px; }\n.grid2 { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }\n@media (max-width: 300px) { .grid2 { grid-template-columns: 1fr; } }\n.hint { color: var(--fg3); font-size: 11px; line-height: 16px; }\n.assign-row { display: flex; gap: 8px; align-items: center; }\n.assign-row .select { flex: 1; height: var(--control); min-width: 0; }\n.radio { display: flex; gap: 8px; align-items: flex-start; padding: 6px 0; }\n.radio input { margin: 2px 0 0; }\n\n/* ---- sheet (ticket editor) and dialog ---- */\n.sheet { position: fixed; inset: 0; background: var(--bg); display: flex; flex-direction: column; z-index: 5; }\n.sheet-head { display: flex; align-items: center; gap: 8px; padding: 10px 12px 10px 16px; border-bottom: 1px solid var(--divider); }\n.sheet-head .key { font: 600 12px/16px var(--mono); color: var(--fg2); }\n.sheet-head .spacer { flex: 1; }\n.sheet-body { flex: 1; overflow-y: auto; padding: 14px 16px; display: grid; gap: 12px; align-content: start; }\n.sheet-foot { display: flex; gap: 8px; padding: 10px 16px; border-top: 1px solid var(--divider); align-items: center; flex-wrap: wrap; }\n.sheet-foot .spacer { flex: 1; }\n.scrim { position: fixed; inset: 0; background: var(--scrim); display: flex; align-items: flex-start; justify-content: center; padding: 40px 12px 12px; z-index: 10; }\n.dialog { width: 100%; max-width: 420px; max-height: calc(100vh - 52px); overflow-y: auto; background: var(--raised); border: 1px solid var(--line); border-radius: var(--r-lg); padding: 16px; display: grid; gap: 12px; box-shadow: 0 12px 32px rgba(0, 0, 0, 0.18); }\n.dialog h2 { margin: 0; font-size: 14px; line-height: 20px; font-weight: 600; }\n.dialog .foot { display: flex; justify-content: flex-end; gap: 8px; }\n.summary { display: flex; gap: 16px; padding: 10px 12px; background: var(--well); border-radius: var(--r-md); }\n.summary b { display: block; font-size: 18px; line-height: 22px; font-variant-numeric: tabular-nums; }\n.summary span { color: var(--fg2); font-size: 11px; }\n.note { padding: 8px 10px; border-radius: var(--r-md); background: var(--warning-subtle); color: var(--warning); }\n\n.toast {\n    position: fixed; left: 12px; right: 12px; bottom: 12px; z-index: 20;\n    padding: 10px 12px; border-radius: var(--r-md); background: #212529; color: #fff; box-shadow: 0 6px 20px rgba(0, 0, 0, 0.2);\n}\n.toast.danger { background: #c92a2a; }\n@media (prefers-reduced-motion: no-preference) {\n    .toast { animation: rise 160ms ease-out; }\n    @keyframes rise { from { transform: translateY(6px); opacity: 0; } to { transform: none; opacity: 1; } }\n}\n</style>\n</head>\n<body>\n\n<section id=\"loading\" class=\"center\"><p>Reading the board…</p></section>\n\n<section id=\"denied\" class=\"center\" hidden>\n    <h1>Sprint Board can't open this board</h1>\n    <p>It needs permission to read and edit the canvas, and that was turned down on this device. Remove and reinstall the extension to be asked again.</p>\n</section>\n\n<section id=\"empty\" class=\"center\" hidden>\n    <h1>Start a sprint board</h1>\n    <p>The board goes on the canvas where you're looking: Backlog, To do, In progress, Testing and Done columns, with room below for finished sprints.</p>\n    <form id=\"createForm\" class=\"center\" style=\"padding:0\">\n        <label class=\"field\"><span>Project key</span><input id=\"c-key\" class=\"input\" maxlength=\"10\" placeholder=\"LAOR\" autocomplete=\"off\" required /></label>\n        <label class=\"field\"><span>First sprint (a version works well)</span><input id=\"c-name\" class=\"input\" maxlength=\"80\" placeholder=\"v0.0.6-beta\" autocomplete=\"off\" /></label>\n        <label class=\"field\"><span>Sprint goal</span><input id=\"c-goal\" class=\"input\" maxlength=\"500\" placeholder=\"Optional\" autocomplete=\"off\" /></label>\n        <label class=\"field\"><span>Sprint length</span>\n            <select id=\"c-weeks\" class=\"select input\"><option value=\"1\">1 week</option><option value=\"2\" selected>2 weeks</option><option value=\"3\">3 weeks</option><option value=\"4\">4 weeks</option></select>\n        </label>\n        <div><button class=\"btn primary\" type=\"submit\">Create sprint board</button></div>\n        <p class=\"hint\">Tickets get keys like LAOR-001. Sticky notes you already have can be turned into tickets afterwards.</p>\n    </form>\n</section>\n\n<section id=\"main\" hidden style=\"display:flex;flex-direction:column;flex:1;min-height:0\">\n    <header class=\"top\">\n        <div class=\"crumb\">\n            <span class=\"crumb-text\" id=\"crumb\">Sprint board</span>\n            <button class=\"icon-btn\" id=\"closePanel\" aria-label=\"Close panel\" title=\"Close\"><svg class=\"ic\" viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"><path d=\"M4 4l8 8M12 4l-8 8\"/></svg></button>\n        </div>\n        <div class=\"sprint-row\">\n            <span class=\"sprint-name\" id=\"sprintName\"></span>\n            <button class=\"link\" id=\"editSprint\" type=\"button\">Edit</button>\n        </div>\n        <div class=\"sprint-meta\" id=\"sprintMeta\"></div>\n        <div class=\"sprint-goal\" id=\"sprintGoal\" hidden></div>\n        <div class=\"progress\" id=\"progress\" aria-hidden=\"true\"></div>\n        <div class=\"progress-label\"><span id=\"progressText\"></span><span id=\"pointsText\"></span></div>\n        <div class=\"top-actions\">\n            <button class=\"btn\" id=\"completeBtn\" type=\"button\">Complete sprint</button>\n            <button class=\"btn primary\" id=\"createBtn\" type=\"button\">Create ticket</button>\n        </div>\n    </header>\n    <nav class=\"tabs\" role=\"tablist\">\n        <button class=\"tab\" role=\"tab\" data-tab=\"sprint\" id=\"tab-sprint\">Sprint <span class=\"count\" id=\"n-sprint\">0</span></button>\n        <button class=\"tab\" role=\"tab\" data-tab=\"backlog\" id=\"tab-backlog\">Backlog <span class=\"count\" id=\"n-backlog\">0</span></button>\n        <button class=\"tab\" role=\"tab\" data-tab=\"releases\" id=\"tab-releases\">Releases <span class=\"count\" id=\"n-releases\">0</span></button>\n    </nav>\n    <div class=\"filters\">\n        <input id=\"q\" class=\"search\" type=\"search\" placeholder=\"Search keys, titles and descriptions\" autocomplete=\"off\" />\n        <div class=\"chips\" id=\"people\"></div>\n        <div class=\"filter-row\">\n            <select id=\"fType\" class=\"select\" aria-label=\"Type\"><option value=\"\">All types</option><option value=\"feature\">Feature</option><option value=\"bug\">Bug</option><option value=\"chore\">Chore</option></select>\n            <select id=\"fPrio\" class=\"select\" aria-label=\"Priority\"><option value=\"\">All priorities</option><option value=\"p1\">P1 · Now</option><option value=\"p2\">P2 · Soon</option><option value=\"p3\">P3 · Later</option></select>\n            <button class=\"link\" id=\"clearFilters\" type=\"button\" hidden>Clear filters</button>\n            <span class=\"spacer\"></span>\n            <button class=\"mini\" id=\"showOnBoard\" type=\"button\">Show on board</button>\n        </div>\n    </div>\n    <div class=\"list\" id=\"list\"></div>\n</section>\n\n<section id=\"sheet\" class=\"sheet\" hidden aria-label=\"Ticket\">\n    <div class=\"sheet-head\">\n        <span class=\"key\" id=\"s-key\">New ticket</span>\n        <span class=\"spacer\"></span>\n        <button class=\"icon-btn\" id=\"s-close\" aria-label=\"Close ticket\" title=\"Close\"><svg class=\"ic\" viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"><path d=\"M4 4l8 8M12 4l-8 8\"/></svg></button>\n    </div>\n    <form id=\"ticketForm\" class=\"sheet-body\">\n        <label class=\"field\"><span>Title</span><input id=\"t-title\" class=\"input\" maxlength=\"300\" required autocomplete=\"off\" /></label>\n        <label class=\"field\"><span>Description</span><textarea id=\"t-desc\" class=\"textarea\" maxlength=\"4000\"></textarea></label>\n        <div class=\"grid2\">\n            <label class=\"field\"><span>Status</span><select id=\"t-status\" class=\"select input\"></select></label>\n            <label class=\"field\"><span>Type</span><select id=\"t-type\" class=\"select input\"><option value=\"feature\">Feature</option><option value=\"bug\">Bug</option><option value=\"chore\">Chore</option></select></label>\n            <label class=\"field\"><span>Priority</span><select id=\"t-prio\" class=\"select input\"><option value=\"p1\">P1 · Now</option><option value=\"p2\">P2 · Soon</option><option value=\"p3\">P3 · Later</option></select></label>\n            <label class=\"field\"><span>Story points</span><input id=\"t-points\" class=\"input\" type=\"number\" min=\"0\" step=\"0.5\" inputmode=\"decimal\" /></label>\n        </div>\n        <div class=\"field\">\n            <span>Assignee</span>\n            <div class=\"assign-row\">\n                <select id=\"t-assignee\" class=\"select\" aria-label=\"Assignee\"></select>\n                <button class=\"link\" id=\"t-me\" type=\"button\" hidden>Assign to me</button>\n            </div>\n            <input id=\"t-other\" class=\"input\" maxlength=\"80\" placeholder=\"Name\" autocomplete=\"off\" hidden />\n            <span class=\"hint\" id=\"t-people-hint\"></span>\n        </div>\n        <span class=\"hint\" id=\"t-stamp\"></span>\n    </form>\n    <div class=\"sheet-foot\">\n        <button class=\"btn danger\" id=\"t-delete\" type=\"button\">Delete</button>\n        <button class=\"btn danger solid\" id=\"t-delete-yes\" type=\"button\" hidden>Delete ticket</button>\n        <button class=\"btn ghost\" id=\"t-delete-no\" type=\"button\" hidden>Keep</button>\n        <button class=\"mini\" id=\"t-show\" type=\"button\">Show on board</button>\n        <span class=\"spacer\"></span>\n        <button class=\"btn ghost\" id=\"t-cancel\" type=\"button\">Cancel</button>\n        <button class=\"btn primary\" id=\"t-save\" type=\"submit\" form=\"ticketForm\">Save</button>\n    </div>\n</section>\n\n<div class=\"scrim\" id=\"completeDialog\" hidden>\n    <form class=\"dialog\" id=\"completeForm\" aria-labelledby=\"completeTitle\">\n        <h2 id=\"completeTitle\">Complete sprint</h2>\n        <div class=\"summary\"><div><b id=\"cd-done\">0</b><span>done, go to the version log</span></div><div><b id=\"cd-open\">0</b><span>not done</span></div></div>\n        <div class=\"note\" id=\"cd-nothing\" hidden>Nothing is done yet. The sprint will be archived with no finished tickets.</div>\n        <div id=\"cd-openChoice\">\n            <label class=\"radio\"><input type=\"radio\" name=\"moveOpenTo\" value=\"next\" checked /><span>Carry the unfinished tickets into the next sprint</span></label>\n            <label class=\"radio\"><input type=\"radio\" name=\"moveOpenTo\" value=\"backlog\" /><span>Move them back to the backlog</span></label>\n        </div>\n        <label class=\"field\"><span>Next sprint</span><input id=\"cd-name\" class=\"input\" maxlength=\"80\" autocomplete=\"off\" required /></label>\n        <label class=\"field\"><span>Next sprint goal</span><input id=\"cd-goal\" class=\"input\" maxlength=\"500\" placeholder=\"Optional\" autocomplete=\"off\" /></label>\n        <label class=\"field\"><span>Length</span>\n            <select id=\"cd-weeks\" class=\"select input\"><option value=\"1\">1 week</option><option value=\"2\">2 weeks</option><option value=\"3\">3 weeks</option><option value=\"4\">4 weeks</option></select>\n        </label>\n        <label class=\"field\"><span>Release notes for the version log</span><textarea id=\"cd-notes\" class=\"textarea\" maxlength=\"4000\" placeholder=\"One line per change\"></textarea></label>\n        <div class=\"foot\"><button class=\"btn ghost\" type=\"button\" data-close>Cancel</button><button class=\"btn primary\" type=\"submit\">Complete sprint</button></div>\n    </form>\n</div>\n\n<div class=\"scrim\" id=\"sprintDialog\" hidden>\n    <form class=\"dialog\" id=\"sprintForm\" aria-labelledby=\"sprintTitle\">\n        <h2 id=\"sprintTitle\">Edit sprint</h2>\n        <label class=\"field\"><span>Name</span><input id=\"sd-name\" class=\"input\" maxlength=\"80\" required autocomplete=\"off\" /></label>\n        <label class=\"field\"><span>Goal</span><input id=\"sd-goal\" class=\"input\" maxlength=\"500\" autocomplete=\"off\" /></label>\n        <div class=\"grid2\">\n            <label class=\"field\"><span>Starts</span><input id=\"sd-start\" class=\"input\" type=\"date\" required /></label>\n            <label class=\"field\"><span>Ends</span><input id=\"sd-end\" class=\"input\" type=\"date\" required /></label>\n        </div>\n        <div class=\"foot\"><button class=\"btn ghost\" type=\"button\" data-close>Cancel</button><button class=\"btn primary\" type=\"submit\">Save sprint</button></div>\n    </form>\n</div>\n\n<div class=\"toast\" id=\"toast\" role=\"status\" hidden></div>\n\n<script>\n(function () {\n    \"use strict\";\n    var api = acquireDrawdyApi();\n\n    var STATUSES = [\n        { id: \"backlog\", label: \"Backlog\", color: \"#868e96\" },\n        { id: \"todo\", label: \"To do\", color: \"#4263eb\" },\n        { id: \"inprogress\", label: \"In progress\", color: \"#e8590c\" },\n        { id: \"testing\", label: \"Testing\", color: \"#ae3ec9\" },\n        { id: \"done\", label: \"Done\", color: \"#2f9e44\" }\n    ];\n    var SPRINT_STATUSES = [\"todo\", \"inprogress\", \"testing\", \"done\"];\n    var MONTHS = [\"Jan\", \"Feb\", \"Mar\", \"Apr\", \"May\", \"Jun\", \"Jul\", \"Aug\", \"Sep\", \"Oct\", \"Nov\", \"Dec\"];\n\n    var S = { sceneAllowed: true, hasBoard: false, keyPrefix: \"\", sprint: null, archive: [], tickets: [], people: [], me: null, today: \"\" };\n    var loaded = false;\n    var ui = { tab: \"sprint\", q: \"\", who: {}, mine: false, type: \"\", prio: \"\", sheet: null, peopleAsked: false, highlight: null };\n\n    function $(id) { return document.getElementById(id); }\n    function el(tag, cls, text) {\n        var e = document.createElement(tag);\n        if (cls) e.className = cls;\n        if (text !== undefined && text !== null) e.textContent = text;\n        return e;\n    }\n    function send(type, data) {\n        var m = data || {};\n        m.type = type;\n        api.postMessage(m);\n    }\n    function statusOf(id) {\n        for (var i = 0; i < STATUSES.length; i++) if (STATUSES[i].id === id) return STATUSES[i];\n        return STATUSES[1];\n    }\n\n    // ---- small helpers ----\n\n    function personKey(p) { return p.userId ? p.userId : \"name:\" + p.name.toLowerCase(); }\n    function samePerson(a, b) {\n        if (!a || !b) return false;\n        if (a.userId && b.userId) return a.userId === b.userId;\n        return a.name.toLowerCase() === b.name.toLowerCase();\n    }\n    function initials(name) {\n        var parts = name.trim().split(/\\s+/);\n        var s = parts[0] ? parts[0].charAt(0) : \"?\";\n        if (parts.length > 1) s += parts[parts.length - 1].charAt(0);\n        return s.toUpperCase();\n    }\n    function avatar(p) {\n        var a = el(\"span\", \"avatar\" + (p ? \"\" : \" empty\"), p ? initials(p.name) : \"\");\n        if (p) { a.style.background = p.color || \"#868e96\"; a.title = p.name; }\n        else a.title = \"Unassigned\";\n        return a;\n    }\n    function dayLabel(iso, withYear) {\n        var m = /^(\\d{4})-(\\d{2})-(\\d{2})$/.exec(iso || \"\");\n        if (!m) return iso || \"\";\n        return MONTHS[Number(m[2]) - 1] + \" \" + Number(m[3]) + (withYear ? \", \" + m[1] : \"\");\n    }\n    function dayNumber(iso) {\n        var m = /^(\\d{4})-(\\d{2})-(\\d{2})$/.exec(iso || \"\");\n        return m ? Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])) / 86400000 : NaN;\n    }\n    function bumpName(name) {\n        var t = (name || \"\").trim();\n        if (!t) return \"Sprint 1\";\n        var m = /^(.*?)(\\d+)(\\D*)$/.exec(t);\n        return m ? m[1] + (Number(m[2]) + 1) + m[3] : t + \" 2\";\n    }\n    function plural(n, one, many) { return n + \" \" + (n === 1 ? one : many); }\n\n    var SVG = \"http://www.w3.org/2000/svg\";\n    function icon(paths, fill) {\n        var s = document.createElementNS(SVG, \"svg\");\n        s.setAttribute(\"viewBox\", \"0 0 16 16\");\n        s.setAttribute(\"class\", \"ic\");\n        s.setAttribute(\"aria-hidden\", \"true\");\n        var rect = document.createElementNS(SVG, \"rect\");\n        rect.setAttribute(\"x\", \"1\"); rect.setAttribute(\"y\", \"1\"); rect.setAttribute(\"width\", \"14\"); rect.setAttribute(\"height\", \"14\");\n        rect.setAttribute(\"rx\", \"3\"); rect.setAttribute(\"fill\", fill);\n        s.appendChild(rect);\n        var p = document.createElementNS(SVG, \"path\");\n        p.setAttribute(\"d\", paths); p.setAttribute(\"fill\", \"none\"); p.setAttribute(\"stroke\", \"#fff\");\n        p.setAttribute(\"stroke-width\", \"1.7\"); p.setAttribute(\"stroke-linecap\", \"round\"); p.setAttribute(\"stroke-linejoin\", \"round\");\n        s.appendChild(p);\n        return s;\n    }\n    function typeIcon(type) {\n        var s;\n        if (type === \"bug\") s = icon(\"M8 5.2v3.6M8 11h.01\", \"#e03131\");\n        else if (type === \"chore\") s = icon(\"M4.8 8.2l2.1 2.1 4.3-4.6\", \"#5c7080\");\n        else s = icon(\"M5.5 4.5h5v7L8 9.6l-2.5 1.9z\", \"#4263eb\");\n        s.setAttribute(\"aria-label\", type === \"bug\" ? \"Bug\" : type === \"chore\" ? \"Chore\" : \"Feature\");\n        return s;\n    }\n    function prioIcon(prio) {\n        var s = document.createElementNS(SVG, \"svg\");\n        s.setAttribute(\"viewBox\", \"0 0 16 16\");\n        s.setAttribute(\"class\", \"ic\");\n        var p = document.createElementNS(SVG, \"path\");\n        var color = prio === \"p1\" ? \"#e03131\" : prio === \"p2\" ? \"#f08c00\" : \"#868e96\";\n        p.setAttribute(\"d\", prio === \"p1\" ? \"M4 9l4-4 4 4M4 13l4-4 4 4\" : prio === \"p2\" ? \"M4 10l4-4 4 4\" : \"M4 6l4 4 4-4\");\n        p.setAttribute(\"fill\", \"none\"); p.setAttribute(\"stroke\", color); p.setAttribute(\"stroke-width\", \"1.8\");\n        p.setAttribute(\"stroke-linecap\", \"round\"); p.setAttribute(\"stroke-linejoin\", \"round\");\n        s.appendChild(p);\n        var title = document.createElementNS(SVG, \"title\");\n        title.textContent = prio === \"p1\" ? \"P1 · Now\" : prio === \"p2\" ? \"P2 · Soon\" : \"P3 · Later\";\n        s.appendChild(title);\n        return s;\n    }\n\n    // ---- filters ----\n\n    function filtersActive() {\n        return !!(ui.q || ui.type || ui.prio || ui.mine || Object.keys(ui.who).length);\n    }\n    function matches(t) {\n        if (ui.q) {\n            var hay = (t.key + \" \" + t.title + \" \" + (t.description || \"\")).toLowerCase();\n            if (hay.indexOf(ui.q.toLowerCase()) === -1) return false;\n        }\n        if (ui.type && t.type !== ui.type) return false;\n        if (ui.prio && t.priority !== ui.prio) return false;\n        if (ui.mine && !(S.me && samePerson(t.assignee, S.me))) return false;\n        var picked = Object.keys(ui.who);\n        if (picked.length) {\n            var k = t.assignee ? personKey(t.assignee) : \"__none\";\n            if (!ui.who[k]) return false;\n        }\n        return true;\n    }\n\n    // ---- rendering ----\n\n    function show(id) {\n        [\"loading\", \"denied\", \"empty\", \"main\"].forEach(function (s) { $(s).hidden = s !== id; });\n    }\n\n    function render() {\n        if (!loaded) return show(\"loading\");\n        if (!S.sceneAllowed) return show(\"denied\");\n        if (!S.hasBoard) return show(\"empty\");\n        show(\"main\");\n        renderHeader();\n        renderTabs();\n        renderPeople();\n        renderList();\n    }\n\n    function sprintTickets() {\n        return S.tickets.filter(function (t) { return SPRINT_STATUSES.indexOf(t.status) !== -1; });\n    }\n\n    function renderHeader() {\n        var sp = S.sprint || { name: \"Sprint\", startDate: \"\", endDate: \"\", goal: \"\" };\n        $(\"crumb\").textContent = S.keyPrefix + \" · Active sprint\";\n        $(\"sprintName\").textContent = sp.name;\n        var left = dayNumber(sp.endDate) - dayNumber(S.today);\n        var when = isNaN(left) ? \"\" : left > 1 ? left + \" days left\" : left === 1 ? \"1 day left\" : left === 0 ? \"Ends today\" : \"Ended \" + plural(-left, \"day\", \"days\") + \" ago\";\n        $(\"sprintMeta\").textContent = dayLabel(sp.startDate) + \" – \" + dayLabel(sp.endDate, true) + (when ? \" · \" + when : \"\");\n        $(\"sprintGoal\").hidden = !sp.goal;\n        $(\"sprintGoal\").textContent = sp.goal ? \"Goal: \" + sp.goal : \"\";\n\n        var all = sprintTickets();\n        var bar = $(\"progress\");\n        bar.textContent = \"\";\n        SPRINT_STATUSES.forEach(function (id) {\n            var n = all.filter(function (t) { return t.status === id; }).length;\n            if (!n) return;\n            var seg = el(\"span\");\n            seg.style.width = (100 * n / all.length) + \"%\";\n            seg.style.background = statusOf(id).color;\n            bar.appendChild(seg);\n        });\n        var done = all.filter(function (t) { return t.status === \"done\"; });\n        $(\"progressText\").textContent = all.length ? done.length + \" of \" + all.length + \" done\" : \"No tickets in this sprint yet\";\n        var pts = 0, donePts = 0;\n        all.forEach(function (t) { if (t.points) { pts += t.points; if (t.status === \"done\") donePts += t.points; } });\n        $(\"pointsText\").textContent = pts ? donePts + \" of \" + pts + \" pts\" : \"\";\n    }\n\n    function renderTabs() {\n        $(\"n-sprint\").textContent = sprintTickets().length;\n        $(\"n-backlog\").textContent = S.tickets.filter(function (t) { return t.status === \"backlog\"; }).length;\n        $(\"n-releases\").textContent = S.archive.length;\n        [\"sprint\", \"backlog\", \"releases\"].forEach(function (id) {\n            $(\"tab-\" + id).setAttribute(\"aria-selected\", ui.tab === id ? \"true\" : \"false\");\n        });\n        $(\"showOnBoard\").hidden = ui.tab === \"releases\";\n        $(\"clearFilters\").hidden = !filtersActive();\n    }\n\n    function assignedPeople() {\n        var seen = {}, list = [];\n        S.tickets.forEach(function (t) {\n            if (t.assignee && !seen[personKey(t.assignee)]) { seen[personKey(t.assignee)] = 1; list.push(t.assignee); }\n        });\n        S.archive.forEach(function (r) {\n            r.done.forEach(function (t) {\n                if (t.assignee && !seen[personKey(t.assignee)]) { seen[personKey(t.assignee)] = 1; list.push(t.assignee); }\n            });\n        });\n        return list.sort(function (a, b) { return a.name.localeCompare(b.name); });\n    }\n\n    function renderPeople() {\n        var box = $(\"people\");\n        box.textContent = \"\";\n        var mine = el(\"button\", \"chip plain\", \"Only my issues\");\n        mine.type = \"button\";\n        mine.setAttribute(\"aria-pressed\", ui.mine ? \"true\" : \"false\");\n        mine.addEventListener(\"click\", function () {\n            ui.mine = !ui.mine;\n            if (ui.mine && !S.me && !ui.peopleAsked) { ui.peopleAsked = true; send(\"people\"); }\n            render();\n        });\n        box.appendChild(mine);\n        assignedPeople().forEach(function (p) {\n            var k = personKey(p);\n            var chip = el(\"button\", \"chip\");\n            chip.type = \"button\";\n            chip.appendChild(avatar(p));\n            chip.appendChild(document.createTextNode(p.name));\n            chip.setAttribute(\"aria-pressed\", ui.who[k] ? \"true\" : \"false\");\n            chip.addEventListener(\"click\", function () {\n                if (ui.who[k]) delete ui.who[k]; else ui.who[k] = true;\n                render();\n            });\n            box.appendChild(chip);\n        });\n        var none = el(\"button\", \"chip\");\n        none.type = \"button\";\n        none.appendChild(avatar(null));\n        none.appendChild(document.createTextNode(\"Unassigned\"));\n        none.setAttribute(\"aria-pressed\", ui.who.__none ? \"true\" : \"false\");\n        none.addEventListener(\"click\", function () {\n            if (ui.who.__none) delete ui.who.__none; else ui.who.__none = true;\n            render();\n        });\n        box.appendChild(none);\n    }\n\n    function ticketRow(t, extra) {\n        var row = el(\"button\", \"row\" + (ui.highlight === t.cardId ? \" highlight\" : \"\"));\n        row.type = \"button\";\n        row.dataset.card = t.cardId;\n        row.appendChild(typeIcon(t.type));\n        row.appendChild(el(\"span\", \"key\", t.key));\n        row.appendChild(el(\"span\", \"title\", t.title));\n        row.appendChild(prioIcon(t.priority));\n        row.appendChild(t.points ? el(\"span\", \"pts\", String(t.points)) : el(\"span\"));\n        row.appendChild(avatar(t.assignee));\n        row.title = t.title;\n        row.addEventListener(\"click\", function () { openSheet(t); });\n        if (!extra) return row;\n        var wrap = el(\"div\", \"row-wrap\");\n        wrap.appendChild(row);\n        wrap.appendChild(extra);\n        return wrap;\n    }\n\n    function groupHead(status, n) {\n        var h = el(\"div\", \"group-head\");\n        var dot = el(\"span\", \"dot\");\n        dot.style.background = status.color;\n        h.appendChild(dot);\n        h.appendChild(el(\"span\", \"\", status.label));\n        h.appendChild(el(\"span\", \"count\", String(n)));\n        return h;\n    }\n\n    function byOrder(a, b) { return a.order - b.order; }\n\n    function renderList() {\n        var list = $(\"list\");\n        list.textContent = \"\";\n        if (ui.tab === \"releases\") return renderReleases(list);\n\n        var statuses = ui.tab === \"backlog\" ? [\"backlog\"] : SPRINT_STATUSES;\n        var shown = 0;\n        statuses.forEach(function (id) {\n            var all = S.tickets.filter(function (t) { return t.status === id; });\n            var visible = all.filter(matches).sort(byOrder);\n            shown += visible.length;\n            if (ui.tab === \"sprint\") list.appendChild(groupHead(statusOf(id), visible.length));\n            if (!visible.length) {\n                list.appendChild(el(\"div\", \"none\", all.length ? \"No tickets match the filters.\" : ui.tab === \"backlog\" ? \"The backlog is empty.\" : \"No tickets.\"));\n                return;\n            }\n            visible.forEach(function (t) {\n                var extra = null;\n                if (id === \"backlog\") {\n                    extra = el(\"button\", \"mini\", \"Add to sprint\");\n                    extra.type = \"button\";\n                    extra.addEventListener(\"click\", function () { send(\"update-ticket\", { cardId: t.cardId, patch: { status: \"todo\" } }); });\n                }\n                list.appendChild(ticketRow(t, extra));\n            });\n        });\n        if (ui.tab === \"backlog\") {\n            var box = el(\"div\", \"import-box\");\n            box.appendChild(el(\"span\", \"\", \"Already have sticky notes or cards for this work? Select them on the canvas, then turn them into tickets. Keys like \" + S.keyPrefix + \"-007 are kept.\"));\n            var b = el(\"button\", \"btn\", \"Turn selection into tickets\");\n            b.type = \"button\";\n            b.addEventListener(\"click\", function () { send(\"import-selection\"); });\n            box.appendChild(b);\n            list.appendChild(box);\n        }\n        $(\"showOnBoard\").disabled = shown === 0;\n    }\n\n    function renderReleases(list) {\n        if (!S.archive.length) {\n            list.appendChild(el(\"div\", \"none\", \"No completed sprints yet. When you complete a sprint, its finished tickets land here as one version, and on the canvas in the Sprint archive frame.\"));\n            return;\n        }\n        var any = false;\n        S.archive.forEach(function (r) {\n            var done = r.done.filter(matches);\n            if (filtersActive() && !done.length) return;\n            any = true;\n            var card = el(\"article\", \"release\");\n            var head = el(\"div\", \"release-head\");\n            head.appendChild(el(\"span\", \"release-name\", r.name));\n            var go = el(\"button\", \"link\", \"Show on board\");\n            go.type = \"button\";\n            go.addEventListener(\"click\", function () { send(\"show-release\", { sprintId: r.id }); });\n            head.appendChild(go);\n            card.appendChild(head);\n            var counts = [plural(r.done.length, \"ticket\", \"tickets\") + \" done\"];\n            if (r.carriedOver.length) counts.push(r.carriedOver.length + \" carried over\");\n            if (r.movedToBacklog.length) counts.push(r.movedToBacklog.length + \" back to backlog\");\n            card.appendChild(el(\"div\", \"release-meta\", \"Released \" + dayLabel(r.completedAt, true) + \" · \" + dayLabel(r.startDate) + \" – \" + dayLabel(r.endDate) + \" · \" + counts.join(\", \")));\n            if (r.goal) card.appendChild(el(\"div\", \"release-notes\", \"Goal: \" + r.goal));\n            if (r.notes) card.appendChild(el(\"div\", \"release-notes\", r.notes));\n            done.forEach(function (t) {\n                var item = el(\"div\", \"release-item\");\n                item.appendChild(typeIcon(t.type));\n                item.appendChild(el(\"span\", \"key\", t.key));\n                item.appendChild(el(\"span\", \"title\", t.title));\n                item.appendChild(avatar(t.assignee));\n                item.title = t.title;\n                card.appendChild(item);\n            });\n            list.appendChild(card);\n        });\n        if (!any) list.appendChild(el(\"div\", \"none\", \"No released tickets match the filters.\"));\n    }\n\n    // ---- ticket sheet ----\n\n    function fillStatusOptions(select) {\n        select.textContent = \"\";\n        STATUSES.forEach(function (s) {\n            var o = el(\"option\", \"\", s.label);\n            o.value = s.id;\n            select.appendChild(o);\n        });\n    }\n    fillStatusOptions($(\"t-status\"));\n\n    function peopleForPicker(current) {\n        var list = S.people.slice();\n        if (current && !list.some(function (p) { return samePerson(p, current); })) list.push(current);\n        return list.sort(function (a, b) { return a.name.localeCompare(b.name); });\n    }\n\n    function fillAssignee(current) {\n        var sel = $(\"t-assignee\");\n        sel.textContent = \"\";\n        var none = el(\"option\", \"\", \"Unassigned\");\n        none.value = \"__none\";\n        sel.appendChild(none);\n        var people = peopleForPicker(current);\n        people.forEach(function (p) {\n            var o = el(\"option\", \"\", p.name + (S.me && samePerson(p, S.me) ? \" (you)\" : \"\"));\n            o.value = personKey(p);\n            sel.appendChild(o);\n        });\n        var other = el(\"option\", \"\", \"Someone else…\");\n        other.value = \"__other\";\n        sel.appendChild(other);\n        sel.value = current ? personKey(current) : \"__none\";\n        $(\"t-other\").hidden = true;\n        $(\"t-me\").hidden = !S.me || samePerson(current, S.me);\n        $(\"t-people-hint\").textContent = S.people.length ? \"\" : \"People on this board appear here once Sprint Board can see who's on it.\";\n    }\n\n    function chosenAssignee() {\n        var v = $(\"t-assignee\").value;\n        if (v === \"__none\") return null;\n        if (v === \"__other\") {\n            var name = $(\"t-other\").value.trim();\n            return name ? { name: name, color: \"\", userId: null } : null;\n        }\n        var people = peopleForPicker(ui.sheet && ui.sheet.ticket ? ui.sheet.ticket.assignee : null);\n        for (var i = 0; i < people.length; i++) if (personKey(people[i]) === v) return people[i];\n        return null;\n    }\n\n    function openSheet(t, status) {\n        if (!ui.peopleAsked) { ui.peopleAsked = true; send(\"people\"); }\n        ui.sheet = { ticket: t || null, dirty: false };\n        ui.highlight = t ? t.cardId : ui.highlight;\n        $(\"s-key\").textContent = t ? t.key : \"New ticket\";\n        $(\"t-title\").value = t ? t.title : \"\";\n        $(\"t-desc\").value = t ? t.description || \"\" : \"\";\n        $(\"t-status\").value = t ? t.status : status || (ui.tab === \"backlog\" ? \"backlog\" : \"todo\");\n        $(\"t-type\").value = t ? t.type : \"feature\";\n        $(\"t-prio\").value = t ? t.priority : \"p2\";\n        $(\"t-points\").value = t && t.points !== null && t.points !== undefined ? String(t.points) : \"\";\n        fillAssignee(t ? t.assignee : null);\n        $(\"t-stamp\").textContent = t ? \"Created \" + dayLabel((t.createdAt || \"\").slice(0, 10), true) + \" · updated \" + dayLabel((t.updatedAt || \"\").slice(0, 10), true) : \"\";\n        $(\"t-delete\").hidden = !t;\n        $(\"t-delete-yes\").hidden = true;\n        $(\"t-delete-no\").hidden = true;\n        $(\"t-show\").hidden = !t;\n        $(\"t-save\").textContent = t ? \"Save\" : \"Create ticket\";\n        $(\"sheet\").hidden = false;\n        $(\"t-title\").focus();\n    }\n\n    function closeSheet() {\n        ui.sheet = null;\n        $(\"sheet\").hidden = true;\n        render();\n    }\n\n    $(\"ticketForm\").addEventListener(\"input\", function () { if (ui.sheet) ui.sheet.dirty = true; });\n    $(\"ticketForm\").addEventListener(\"change\", function () { if (ui.sheet) ui.sheet.dirty = true; });\n    $(\"t-assignee\").addEventListener(\"change\", function () {\n        var other = $(\"t-assignee\").value === \"__other\";\n        $(\"t-other\").hidden = !other;\n        if (other) $(\"t-other\").focus();\n    });\n    $(\"t-me\").addEventListener(\"click\", function () {\n        if (!S.me) return;\n        $(\"t-assignee\").value = personKey(S.me);\n        $(\"t-other\").hidden = true;\n        $(\"t-me\").hidden = true;\n        if (ui.sheet) ui.sheet.dirty = true;\n    });\n    $(\"ticketForm\").addEventListener(\"submit\", function (e) {\n        e.preventDefault();\n        if (!ui.sheet) return;\n        var title = $(\"t-title\").value.trim();\n        if (!title) { $(\"t-title\").focus(); return; }\n        var pointsRaw = $(\"t-points\").value.trim();\n        var fields = {\n            title: title,\n            description: $(\"t-desc\").value,\n            status: $(\"t-status\").value,\n            type: $(\"t-type\").value,\n            priority: $(\"t-prio\").value,\n            points: pointsRaw === \"\" ? null : Number(pointsRaw),\n            assignee: chosenAssignee()\n        };\n        if (ui.sheet.ticket) send(\"update-ticket\", { cardId: ui.sheet.ticket.cardId, patch: fields });\n        else send(\"create-ticket\", { ticket: fields });\n        closeSheet();\n    });\n    $(\"t-cancel\").addEventListener(\"click\", closeSheet);\n    $(\"s-close\").addEventListener(\"click\", closeSheet);\n    $(\"t-show\").addEventListener(\"click\", function () {\n        if (ui.sheet && ui.sheet.ticket) send(\"show-cards\", { cardIds: [ui.sheet.ticket.cardId] });\n    });\n    $(\"t-delete\").addEventListener(\"click\", function () {\n        $(\"t-delete\").hidden = true;\n        $(\"t-delete-yes\").hidden = false;\n        $(\"t-delete-no\").hidden = false;\n    });\n    $(\"t-delete-no\").addEventListener(\"click\", function () {\n        $(\"t-delete\").hidden = false;\n        $(\"t-delete-yes\").hidden = true;\n        $(\"t-delete-no\").hidden = true;\n    });\n    $(\"t-delete-yes\").addEventListener(\"click\", function () {\n        if (ui.sheet && ui.sheet.ticket) send(\"delete-ticket\", { cardId: ui.sheet.ticket.cardId });\n        closeSheet();\n    });\n\n    // ---- dialogs ----\n\n    function openDialog(id) { $(id).hidden = false; var first = $(id).querySelector(\"input, textarea, select\"); if (first) first.focus(); }\n    function closeDialogs() { $(\"completeDialog\").hidden = true; $(\"sprintDialog\").hidden = true; }\n    Array.prototype.forEach.call(document.querySelectorAll(\"[data-close]\"), function (b) { b.addEventListener(\"click\", closeDialogs); });\n    Array.prototype.forEach.call(document.querySelectorAll(\".scrim\"), function (s) {\n        s.addEventListener(\"click\", function (e) { if (e.target === s) closeDialogs(); });\n    });\n\n    function openComplete() {\n        if (!S.hasBoard) return;\n        var all = sprintTickets();\n        var done = all.filter(function (t) { return t.status === \"done\"; }).length;\n        var open = all.length - done;\n        $(\"cd-done\").textContent = done;\n        $(\"cd-open\").textContent = open;\n        $(\"cd-nothing\").hidden = done > 0;\n        $(\"cd-openChoice\").hidden = open === 0;\n        $(\"cd-name\").value = bumpName(S.sprint ? S.sprint.name : \"\");\n        $(\"cd-goal\").value = \"\";\n        $(\"cd-notes\").value = \"\";\n        var days = S.sprint ? dayNumber(S.sprint.endDate) - dayNumber(S.sprint.startDate) : 14;\n        var weeks = Math.min(4, Math.max(1, Math.round((isNaN(days) ? 14 : days) / 7)));\n        $(\"cd-weeks\").value = String(weeks);\n        openDialog(\"completeDialog\");\n    }\n    $(\"completeForm\").addEventListener(\"submit\", function (e) {\n        e.preventDefault();\n        var choice = document.querySelector(\"input[name=moveOpenTo]:checked\");\n        send(\"complete-sprint\", {\n            moveOpenTo: choice ? choice.value : \"next\",\n            nextName: $(\"cd-name\").value,\n            nextGoal: $(\"cd-goal\").value,\n            weeks: Number($(\"cd-weeks\").value),\n            notes: $(\"cd-notes\").value\n        });\n        closeDialogs();\n    });\n\n    $(\"editSprint\").addEventListener(\"click\", function () {\n        if (!S.sprint) return;\n        $(\"sd-name\").value = S.sprint.name;\n        $(\"sd-goal\").value = S.sprint.goal || \"\";\n        $(\"sd-start\").value = S.sprint.startDate;\n        $(\"sd-end\").value = S.sprint.endDate;\n        openDialog(\"sprintDialog\");\n    });\n    $(\"sprintForm\").addEventListener(\"submit\", function (e) {\n        e.preventDefault();\n        send(\"update-sprint\", { patch: { name: $(\"sd-name\").value, goal: $(\"sd-goal\").value, startDate: $(\"sd-start\").value, endDate: $(\"sd-end\").value } });\n        closeDialogs();\n    });\n\n    // ---- header, tabs, filters ----\n\n    $(\"completeBtn\").addEventListener(\"click\", openComplete);\n    $(\"createBtn\").addEventListener(\"click\", function () { openSheet(null); });\n    $(\"closePanel\").addEventListener(\"click\", function () { send(\"close\"); });\n    Array.prototype.forEach.call(document.querySelectorAll(\".tab\"), function (b) {\n        b.addEventListener(\"click\", function () { ui.tab = b.dataset.tab; render(); });\n    });\n    $(\"q\").addEventListener(\"input\", function () { ui.q = $(\"q\").value.trim(); renderTabs(); renderList(); });\n    $(\"fType\").addEventListener(\"change\", function () { ui.type = $(\"fType\").value; render(); });\n    $(\"fPrio\").addEventListener(\"change\", function () { ui.prio = $(\"fPrio\").value; render(); });\n    $(\"clearFilters\").addEventListener(\"click\", function () {\n        ui.q = \"\"; ui.type = \"\"; ui.prio = \"\"; ui.mine = false; ui.who = {};\n        $(\"q\").value = \"\"; $(\"fType\").value = \"\"; $(\"fPrio\").value = \"\";\n        render();\n    });\n    $(\"showOnBoard\").addEventListener(\"click\", function () {\n        var statuses = ui.tab === \"backlog\" ? [\"backlog\"] : SPRINT_STATUSES;\n        var ids = S.tickets.filter(function (t) { return statuses.indexOf(t.status) !== -1 && matches(t); }).map(function (t) { return t.cardId; });\n        send(\"show-cards\", { cardIds: ids });\n    });\n\n    $(\"createForm\").addEventListener(\"submit\", function (e) {\n        e.preventDefault();\n        send(\"create-board\", { keyPrefix: $(\"c-key\").value, sprintName: $(\"c-name\").value, goal: $(\"c-goal\").value, weeks: Number($(\"c-weeks\").value) });\n    });\n\n    document.addEventListener(\"keydown\", function (e) {\n        if (e.key !== \"Escape\") return;\n        if (!$(\"completeDialog\").hidden || !$(\"sprintDialog\").hidden) closeDialogs();\n        else if (ui.sheet) closeSheet();\n    });\n\n    var toastTimer = null;\n    function toast(text, tone) {\n        var t = $(\"toast\");\n        t.textContent = text;\n        t.className = \"toast\" + (tone === \"danger\" ? \" danger\" : \"\");\n        t.hidden = false;\n        if (toastTimer) clearTimeout(toastTimer);\n        toastTimer = setTimeout(function () { t.hidden = true; }, 3800);\n    }\n\n    // ---- messages from the driver ----\n\n    api.onMessage(function (m) {\n        if (!m || typeof m !== \"object\") return;\n        if (m.type === \"theme\") { $(\"theme\").textContent = \":root{\" + m.css + \"}\"; return; }\n        if (m.type === \"toast\") { toast(String(m.text || \"\"), m.tone); return; }\n        if (m.type === \"open\") {\n            if (m.view === \"new-ticket\" && S.hasBoard) openSheet(null);\n            else if (m.view === \"complete\") openComplete();\n            else if (m.view === \"create-board\" && S.hasBoard) toast(\"This canvas already has a sprint board.\");\n            return;\n        }\n        if (m.type === \"select\") {\n            var hit = S.tickets.filter(function (t) { return t.cardId === m.cardId; })[0];\n            if (!hit) return;\n            ui.highlight = hit.cardId;\n            if (ui.sheet && !ui.sheet.dirty) openSheet(hit);\n            else if (!ui.sheet) {\n                if (ui.tab === \"releases\" || (ui.tab === \"backlog\") !== (hit.status === \"backlog\")) ui.tab = hit.status === \"backlog\" ? \"backlog\" : \"sprint\";\n                render();\n                var row = document.querySelector('[data-card=\"' + CSS.escape(hit.cardId) + '\"]');\n                if (row) row.scrollIntoView({ block: \"nearest\" });\n            }\n            return;\n        }\n        if (m.type !== \"state\") return;\n        loaded = true;\n        S.sceneAllowed = m.sceneAllowed !== false;\n        S.hasBoard = !!m.hasBoard;\n        S.keyPrefix = m.keyPrefix || \"\";\n        S.sprint = m.sprint || null;\n        S.archive = Array.isArray(m.archive) ? m.archive : [];\n        S.tickets = Array.isArray(m.tickets) ? m.tickets : [];\n        S.people = Array.isArray(m.people) ? m.people : [];\n        S.me = m.me || null;\n        S.today = m.today || \"\";\n        if (m.view === \"releases\") ui.tab = \"releases\";\n        if (m.focusCardId) ui.highlight = m.focusCardId;\n        if (ui.sheet && ui.sheet.ticket) {\n            var still = S.tickets.filter(function (t) { return t.cardId === ui.sheet.ticket.cardId; })[0];\n            if (!still) { closeSheet(); toast(\"That ticket was removed from the board.\"); }\n            else {\n                if (!ui.sheet.dirty) ui.sheet.ticket = still;\n                fillAssigneeKeep();\n            }\n        } else if (ui.sheet) {\n            fillAssigneeKeep();\n        }\n        render();\n    });\n\n    /** New people arrived while the editor is open: refresh the picker, keeping the choice. */\n    function fillAssigneeKeep() {\n        var keep = $(\"t-assignee\").value;\n        var otherName = $(\"t-other\").value;\n        fillAssignee(ui.sheet && ui.sheet.ticket ? ui.sheet.ticket.assignee : null);\n        var options = Array.prototype.map.call($(\"t-assignee\").options, function (o) { return o.value; });\n        if (options.indexOf(keep) !== -1) $(\"t-assignee\").value = keep;\n        if (keep === \"__other\") { $(\"t-other\").hidden = false; $(\"t-other\").value = otherName; }\n    }\n\n    render();\n    api.postMessage({ type: \"ready\" });\n})();\n</script>\n</body>\n</html>\n";
